<?php
declare(strict_types=1);define('HWC_SKIP_GLOBAL_SHELL',true);require_once __DIR__.'/config/dynamic_forms.php';$pdo=role_portal_db();dynamic_forms_ensure($pdo);security_step17_session_start();$user=security_step17_session_user($pdo,true);if(!$user||(string)$user['role_code']!=='admin'){header('Location: access_denied.php');exit;}$ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$key=trim((string)($_GET['form']??''));$s=$pdo->prepare("SELECT * FROM dynamic_form_definitions WHERE organization_id=? AND form_key=? AND is_custom=1 LIMIT 1");$s->execute([$orgId,$key]);$form=$s->fetch();if(!$form){http_response_code(404);exit('Form not found.');}$s=$pdo->prepare("SELECT * FROM dynamic_form_fields WHERE organization_id=? AND form_id=? ORDER BY sort_order,id");$s->execute([$orgId,(int)$form['id']]);$fields=$s->fetchAll();$s=$pdo->prepare("SELECT x.*,u.full_name FROM dynamic_form_submissions x LEFT JOIN system_users u ON u.id=x.submitted_by WHERE x.organization_id=? AND x.form_id=? ORDER BY x.id DESC LIMIT 500");$s->execute([$orgId,(int)$form['id']]);$rows=$s->fetchAll();$values=[];if($rows){$ids=array_column($rows,'id');$marks=implode(',',array_fill(0,count($ids),'?'));$q=$pdo->prepare("SELECT submission_id,field_id,field_value FROM dynamic_form_submission_values WHERE organization_id=? AND submission_id IN ($marks)");$q->execute([$orgId,...$ids]);foreach($q->fetchAll() as $v)$values[(int)$v['submission_id']][(int)$v['field_id']]=$v['field_value'];}$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$h($form['form_name'])?> Data</title><style>*{box-sizing:border-box}body{margin:0;background:#f6f8fd;color:#294036;font-family:Inter,Arial}.wrap{padding:18px}.hero,.card{padding:17px;border:1px solid #dce6e0;border-radius:17px;background:#fff;margin-bottom:13px}.hero{background:linear-gradient(135deg,#fff,#eef5ff)}h1{margin:0}.hero p{color:#708078}.btn{display:inline-block;padding:9px 12px;border-radius:9px;background:#5744db;color:#fff;text-decoration:none;font-size:.72rem;font-weight:850}.table{overflow:auto}.table table{width:100%;border-collapse:collapse;min-width:850px}.table th,.table td{padding:11px;border-bottom:1px solid #e7ece9;text-align:left;font-size:.72rem;vertical-align:top}.table th{background:#f4f3ff;color:#5b6075;font-size:.62rem;text-transform:uppercase}.code{font-weight:850;color:#5140cf}.empty{text-align:center;padding:35px;color:#75837c}</style></head><body><main class="wrap"><section class="hero"><h1><?=$h($form['form_name'])?> — Live Data</h1><p><?=count($rows)?> latest database submission(s). Columns are generated automatically from the current form fields.</p><a class="btn" href="dynamic_form_entry.php?form=<?=$h($key)?>">＋ New Entry</a></section><section class="card table"><?php if($rows):?><table><thead><tr><th>Entry</th><th>Submitted</th><th>Entered By</th><?php foreach($fields as $f):?><th><?=$h($f['field_label'])?></th><?php endforeach?></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="code"><?=$h($r['submission_code'])?></td><td><?=$h($r['submitted_at'])?></td><td><?=$h(($r['full_name']?:'User').' · '.strtoupper((string)$r['submitted_role']))?></td><?php foreach($fields as $f):?><td><?=$h($values[(int)$r['id']][(int)$f['id']]??'—')?></td><?php endforeach?></tr><?php endforeach?></tbody></table><?php else:?><div class="empty">No entry has been submitted yet.</div><?php endif?></section></main></body></html>
